\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── World Bank Color Theme ──
\definecolor{primary}{HTML}{0A3A5E}      % deep WB navy blue
\definecolor{secondary}{HTML}{00857D}     % teal
\definecolor{accent}{HTML}{D4A017}       % amber/gold
\definecolor{bgposter}{HTML}{F4F7FA}     % light blue-gray background
\definecolor{bluebg}{HTML}{E9EEF3}       % blue-tinted card bg
\definecolor{tealbg}{HTML}{E8F2F1}       % teal-tinted card bg
\definecolor{goldbg}{HTML}{FBF6EB}       % gold-tinted card bg
\definecolor{darkbg}{HTML}{EBEFF5}       % dark-tinted card bg
\definecolor{bluetitlebg}{HTML}{DCE4EC}  % blue card title bg
\definecolor{tealtitlebg}{HTML}{D4EBE9}  % teal card title bg
\definecolor{goldtitlebg}{HTML}{F5ECDA}  % gold card title bg
\definecolor{darktitlebg}{HTML}{DDE3EB}  % dark card title bg
\definecolor{textdark}{HTML}{1F2937}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEF9EE} % warm stat highlight
\definecolor{riskred}{HTML}{C0392B}       % risk accent

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={4pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={4pt}{0pt}{secondary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=goldtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!12!white,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.18},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════
% TITLE BAR (rows 1-4, span=2)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{54}{64}\selectfont\bfseries Global Economic Prospects}\\[8pt]
  {\fontsize{30}{38}\selectfont Resilience Amid Uncertainty}\\[10pt]
  {\fontsize{20}{26}\selectfont\color{white!65} World Bank Group \hspace{3em} June 2026 \hspace{3em} worldbank.org/gep}
}

% ═══════════════════════════════════════════════════════════
% STATS BANNER (rows 4-7, span=2) — 3 headline metrics
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=6pt, bottom=6pt,
  valign=center, borderline south={2pt}{0pt}{primary!25},
]{name=stats, column=1, span=2, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{primary}Strongest}\\[2pt]
      {\fontsize{36}{44}\selectfont\bfseries\color{primary}in 6 decades}\\[4pt]
      {\fontsize{16}{20}\selectfont\color{textgray}Post-2020 global recovery}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!35}{tealbg!50}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{48}{56}\selectfont\bfseries\color{secondary}1.2 bn}\\[4pt]
      {\fontsize{16}{20}\selectfont\color{textgray}Youth entering working age}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray}in the next decade}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!45}{goldbg!70}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{48}{56}\selectfont\bfseries\color{accent!70!black}1.5 bn}\\[4pt]
      {\fontsize{16}{20}\selectfont\color{textgray}Health services target}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray}by 2030}\vspace{6pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% ROW A (rows 7-13): Recovery Overview + Risks to Outlook
% ═══════════════════════════════════════════════════════════

% --- Col 1: A Historic Recovery — But Uneven ---
\posterbox[bluecard, title={A Historic Recovery --- But Uneven}
]{name=recovery, column=1, between=row7 and row13}{
  \fontsize{20}{28}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Global economy has staged its \textbf{strongest recovery from recession in six decades}
    \item But resilience is \textbf{uneven}: vulnerable EMDEs are falling further behind advanced economies
    \item Current-year growth projected to \textbf{edge downward} as inventory accumulation slows
    \item Tariff effects and trade tensions are compounding the drag on activity
  \end{itemize}

  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont\centering
    \textbf{The gap is widening.} Advanced economies are recovering while vulnerable emerging markets and developing economies face persistent headwinds from high debt, weak investment, and limited fiscal space.
  }}
}

% --- Col 2: Risks to the Outlook ---
\posterbox[tealcard, title={Risks to the Outlook}
]{name=risks, column=2, between=row7 and row13}{
  \fontsize{20}{28}\selectfont
  \vspace{-4pt}

  \colorbox{riskred!12}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont
    \textbf{\color{riskred!85!black}Trade Tensions}\\[3pt]
    Escalation of tariffs and retaliatory measures could disrupt supply chains, raise costs, and sharply dampen cross-border investment.
  }}

  \vspace{6pt}
  \colorbox{secondary!16}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont
    \textbf{\color{secondary!80!black}Financial Volatility}\\[3pt]
    Deteriorating market sentiment could tighten financing conditions, especially for EMDEs with high external debt burdens.
  }}

  \vspace{6pt}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont
    \textbf{\color{accent!75!black}Inventory Correction}\\[3pt]
    Firms that front-loaded purchases are now drawing down stocks, reducing near-term demand and manufacturing output.
  }}

  \vspace{6pt}
  \colorbox{primary!14}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont
    \textbf{\color{primary!85!black}Climate Shocks}\\[3pt]
    Extreme weather events continue to threaten agricultural output and critical infrastructure in the most vulnerable regions.
  }}
}

% ═══════════════════════════════════════════════════════════
% ROW B (rows 13-18): Policy Actions + WB 2030 Priorities
% ═══════════════════════════════════════════════════════════

% --- Col 1: Policy Actions ---
\posterbox[goldcard, title={Policy Actions for Sustained Growth}
]{name=policy, column=1, between=row13 and row18}{
  \fontsize{18}{24}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{p{0.42\linewidth}p{0.50\linewidth}}
    \rowcolor{accent!12} \textbf{Reform Area} & \textbf{Key Action} \\
    Trade & Improve multilateral trade environment \& diversify partners \\
    Finance & Ease external financing constraints for EMDEs \\
    Climate & Scale up risk mitigation \& resilient infrastructure \\
    Investment & Catalyze private capital; remove business bottlenecks \\
    Jobs & Enhance skills \& labor market flexibility \\
  \end{tabular}
}

% --- Col 2: World Bank 2030 Strategic Priorities ---
\posterbox[bluecard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=2, between=row13 and row18}{
  \fontsize{18}{24}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{p{0.55\linewidth}p{0.37\linewidth}}
    \rowcolor{primary!12} \textbf{Initiative} & \textbf{Target} \\
    Health Services & \textbf{1.5 bn} people \\
    Mission 300 (Electricity) & \textbf{300 M} in Africa \\
    AgriConnect & \textbf{300 M} farmers \\
    Capital Support & \textbf{80 M} women \\
    Water Forward & \textbf{1 bn+} people \\
  \end{tabular}

  \vspace{6pt}
  \colorbox{primary!16}{\parbox{0.94\linewidth}{%
    \fontsize{16}{20}\selectfont\centering
    With \textbf{1.2 billion} young people reaching working age, job creation is central to the World Bank Group's mission.
  }}
}

% ═══════════════════════════════════════════════════════════
% ROW C (rows 18-20): Research Themes + Key Takeaways
% ═══════════════════════════════════════════════════════════

% --- Col 1: Key Research Themes ---
\posterbox[tealcard, title={Key Research Themes}
]{name=research, column=1, between=row18 and bottom}{
  \fontsize{17}{22}\selectfont
  \renewcommand{\arraystretch}{1.4}
  \begin{tabular}{p{0.32\linewidth}p{0.60\linewidth}}
    \rowcolor{secondary!10} \textbf{Fiscal Policy} & Rebuilding fiscal space; small states \\
    \rowcolor{secondary!5} \textbf{Trade \& Supply Chains} & High trade costs; global value chains \\
    \rowcolor{secondary!10} \textbf{Commodity Markets} & Price cycles; energy implications \\
    \rowcolor{secondary!5} \textbf{Financial Spillovers} & U.S. rates; rapid debt buildup waves \\
  \end{tabular}
}

% --- Col 2: Key Takeaway ---
\posterbox[highlightcard, title={Strategic Imperative}
]{name=takeaway, column=2, between=row18 and bottom}{
  \fontsize{20}{28}\selectfont\color{textdark}
  \begin{itemize}[itemsep=8pt, label={\color{primary!60}$\blacktriangleright$}]
    \item Sustaining the recovery demands \textbf{coordinated global and domestic action}
    \item Trade tensions and policy uncertainty remain the \textbf{most consequential risks}
    \item Inclusive job creation is paramount --- \textbf{1.2 billion youth} will enter the workforce
  \end{itemize}

  \vspace{4pt}
  {\fontsize{16}{20}\selectfont\color{textgray}\centering
  \textit{World Bank Global Economic Prospects, June 2026}\\[2pt]
  \textit{worldbank.org/gep}
  }
}

\end{tcbposter}
\end{document}

